 predict:{q:"Which fact identifies the VENUE (container)?",opts:["Environmental Research","Effects of microplastics…","14(3)"],a:0,why:"Venue first in your mind — then its locating numbers."},
 examples:[
  {tag:"A — complete",fields:{sourceType:"journal",authors:"Md. Saiful Islam; Gangadhar Andaluri",year:"2026",title:"Mechanistic insights into PFAS adsorption on microplastics: Effects of contaminant properties and water chemistry",journal:"Environmental Research",volume:"297",pages:"124161",doi:"https://doi.org/10.1016/j.envres.2026.124161"},note:"Eight facts, zero gaps."},
  {tag:"B — thin record",fields:{sourceType:"journal",authors:"Tarek Samy",year:"2024",title:"Microgrid control for desert schools",journal:"Energy Reports",volume:"11",pages:"88–99"},note:"No issue, no DOI — still valid."},
  {tag:"C — trap: journal as title",fields:{sourceType:"journal",authors:"Jane Smith",year:"2025",title:"Environmental Research",journal:"Effects of microplastics on freshwater ecosystems",volume:"14",pages:"31–44"},note:"Swapped work and venue — read, don't assume."}],
 build:{notes:["Md. Saiful Islam|AUTHOR","Gangadhar Andaluri|AUTHOR","2026|DATE","Mechanistic insights into PFAS adsorption on microplastics: Effects of contaminant properties and water chemistry|TITLE","Environmental Research|JOURNAL","297|VOLUME","124161|PAGES","doi:10.1016/j.envres.2026.124161|DOI"],order:["author","date","title","journal","volume","pages","doi"]},
 explain:{q:"What does each number after the journal do?",opts:["Volume → issue → pages: venue, edition, location","They decorate the line","They replace the DOI"],a:0,rule:"volume"},
